#define _GNU_SOURCE
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/syscall.h>

int global = 7;          // vive en la zona de datos del programa
int *monton;             // apuntará a memoria pedida con malloc

static void *trabajo(void *arg) {
  int local = 0;         // vive en la pila de ESTE hilo
  printf("hilo %ld: pid=%d tid=%ld  &global=%p  monton=%p  &local=%p\n",
         (long)arg, getpid(), (long)syscall(SYS_gettid),
         (void *)&global, (void *)monton, (void *)&local);
  global++;
  sleep(3);
  return NULL;
}

int main(void) {
  setvbuf(stdout, NULL, _IOLBF, 0);
  monton = malloc(sizeof(int));
  int local = 0;
  printf("main   : pid=%d tid=%ld  &global=%p  monton=%p  &local=%p\n",
         getpid(), (long)syscall(SYS_gettid),
         (void *)&global, (void *)monton, (void *)&local);
  pthread_t t[2];
  for (long i = 1; i <= 2; i++) pthread_create(&t[i - 1], NULL, trabajo, (void *)i);
  sleep(1);
  printf("main   : global ahora vale %d\n", global);
  char cmd[120];
  snprintf(cmd, sizeof cmd, "ls /proc/%d/task; ps -eLf | head -1; ps -eLf | grep ' ./comp' | grep -v grep", getpid());
  system(cmd);
  for (int i = 0; i < 2; i++) pthread_join(t[i], NULL);
  return 0;
}

