#define _GNU_SOURCE
#include <pthread.h>
#include <stdio.h>
#include <time.h>
#include <unistd.h>
#include <sys/wait.h>

static double ahora(void) { struct timespec t; clock_gettime(CLOCK_MONOTONIC, &t); return t.tv_sec + t.tv_nsec / 1e9; }
static void *nada(void *a) { return a; }

int main(void) {
  int N = 10000;
  double t0 = ahora();
  for (int i = 0; i < N; i++) { pthread_t h; pthread_create(&h, NULL, nada, NULL); pthread_join(h, NULL); }
  double t1 = ahora();
  for (int i = 0; i < N; i++) { pid_t p = fork(); if (p == 0) _exit(0); waitpid(p, NULL, 0); }
  double t2 = ahora();
  printf("hilos:    %d en %.3f s  (%.1f us cada uno)\n", N, t1 - t0, (t1 - t0) / N * 1e6);
  printf("procesos: %d en %.3f s  (%.1f us cada uno)\n", N, t2 - t1, (t2 - t1) / N * 1e6);
  return 0;
}
